def _qt_widget_alive(widget) -> bool:
    """True if a PySide widget still has a live C++ object (not deleted/reparent-GC'd)."""
    if widget is None:
        return False
    try:
        from shiboken6 import isValid
        return bool(isValid(widget))
    except Exception:
        try:
            widget.objectName()
            return True
        except RuntimeError:
            return False


def _safe_set_enabled(widget, enabled: bool) -> None:
    if not _qt_widget_alive(widget):
        return
    try:
        widget.setEnabled(bool(enabled))
    except RuntimeError:
        pass


def _safe_set_text(widget, text: str) -> None:
    if not _qt_widget_alive(widget):
        return
    try:
        widget.setText(str(text))
    except RuntimeError:
        pass


def _safe_set_visible(widget, visible: bool) -> None:
    if not _qt_widget_alive(widget):
        return
    try:
        widget.setVisible(bool(visible))
    except RuntimeError:
        pass
